const icon=StockLensIcons.icon;
const $=s=>document.querySelector(s),escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const dateLabel=value=>{if(!value||!Number.isFinite(new Date(value).getTime()))return 'ไม่ระบุเวลา';return new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(value))+' น. (ไทย)';};
let stocks=[];
const stock=symbol=>stocks.find(s=>s.symbol===symbol)||{symbol,name:symbol,thai:'บริษัทที่ติดตาม',currency:'USD',sector:'',url:'#'};
function companyLogo(symbol){const company=stock(symbol),label=escapeHtml(symbol.slice(0,3));return `<span class="company-logo${company.icon?' has-icon':''}" role="img" aria-label="${escapeHtml(company.name)} (${escapeHtml(symbol)})" title="${escapeHtml(company.name)}">${label}${company.icon?`<img src="${escapeHtml(company.icon)}" alt="" width="28" height="28" loading="lazy" decoding="async">`:''}</span>`;}
document.addEventListener('error',event=>{if(event.target.matches?.('.company-logo img')){event.target.parentElement.classList.remove('has-icon');event.target.remove();}},true);
const defaults={watchlist:[],alerts:{daily:true,news:true,trend:true,time:'08:00',scope:'watchlist'},sources:[]};
let authEpoch=0;
function sameSession(epoch,userId){return epoch===authEpoch&&currentUser?.id===userId;}
let state=structuredClone(defaults),committedState=structuredClone(defaults),currentUser=null,stateRevision=0,isSaving=false,lastSaveError='';
let page='overview',newsFilter='all',selectedStock='AAPL',query='',toastTimer;
let newsData={items:[],sources:[]},newsLoading=false,newsError='',newsEpoch=0;
let aiStatus={enabled:true,available:false,model:'qwen3:8b'},aiSummaries={},aiBusy=false,aiQuestionBusy=false,aiError='',aiEpoch=0;
let forecasts={},forecastLoading='',forecastEpoch=0,forecastInterval='1W';
const forecastIntervals={'1D':'รายวัน','1W':'รายสัปดาห์','1M':'รายเดือน'};
function resetForecast(){forecastEpoch++;forecasts={};forecastLoading='';forecastInterval='1W';}
async function loadForecast(symbol=selectedStock){
 if(!currentUser||forecasts[symbol]||forecastLoading===symbol)return;
 const epoch=forecastEpoch,userId=currentUser.id;forecastLoading=symbol;if(page==='insights')render();
 try{const result=await api('/api/forecast?symbol='+encodeURIComponent(symbol),{timeout:20000});if(epoch!==forecastEpoch||currentUser?.id!==userId)return;forecasts[symbol]=result;}
 catch(error){if(epoch!==forecastEpoch)return;forecasts[symbol]={status:'error',error:error.message};if(error.status===401)showSignedOut('login');}
 finally{if(epoch===forecastEpoch){forecastLoading='';if(currentUser&&canRedraw()&&page==='insights')render();}}
}
async function save(){
  if(isSaving||!currentUser)return false;
  const epoch=authEpoch,userId=currentUser.id;isSaving=true;lastSaveError='';
  try{
    const result=await api('/api/state',{method:'PUT',body:{state,userId:currentUser.id,revision:stateRevision}});
    if(!sameSession(epoch,userId))return false;
    const watchlistChanged=JSON.stringify(committedState.watchlist)!==JSON.stringify(result.state.watchlist);state=result.state;stateRevision=result.revision;committedState=structuredClone(state);if(watchlistChanged)loadQuotes();return true;
  }catch(error){
    if(!sameSession(epoch,userId))return false;
    lastSaveError=error.message;state=structuredClone(committedState);
    if(error.status===401)showSignedOut('login');
    if(error.status===409){
      try{const latest=await api('/api/session');if(!latest.user||latest.user.id!==currentUser?.id)showSignedOut('login');else{state=latest.state;stateRevision=latest.revision;committedState=structuredClone(state);if($('#modal').open)$('#modal').close();render();}}catch{showSignedOut('login');}
    }
    toast(error.message);return false;
  }finally{isSaving=false}
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}

function resetNews(){newsEpoch++;newsLoading=false;newsData={items:[],sources:[]};newsError='';}
async function loadNews({redraw=true}={}){
 if(!currentUser||newsLoading)return;const userId=currentUser.id,epoch=++newsEpoch;newsLoading=true;newsError='';
 try{const result=await api('/api/news');if(epoch!==newsEpoch||currentUser?.id!==userId)return;newsData=result;}
 catch(error){if(epoch!==newsEpoch)return;newsError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===newsEpoch){newsLoading=false;if(redraw&&canRedraw()&&currentUser&&['overview','news','alerts','insights'].includes(page))render();}}
}
function resetAI(){aiEpoch++;aiStatus={enabled:true,available:false,provider:'ollama',online:false,model:'qwen3:8b'};aiSummaries={};aiBusy=false;aiQuestionBusy=false;aiError='';}
async function loadAIStatus(){
 if(!currentUser)return;const userId=currentUser.id,epoch=++aiEpoch;
 try{const result=await api('/api/ai/status');if(epoch!==aiEpoch||currentUser?.id!==userId)return;aiStatus=result;}
 catch(error){if(epoch!==aiEpoch)return;aiStatus={enabled:true,available:false,provider:'ollama',online:false,model:'qwen3:8b'};if(error.status===401)showSignedOut('login');}
 finally{if(epoch===aiEpoch&&canRedraw()&&currentUser&&['overview','insights'].includes(page))render();}
}
async function runAISummary(mode='headlines'){
 if(!currentUser||aiBusy||articleBusy||aiQuestionBusy)return;const userId=currentUser.id,epoch=aiEpoch,symbol=selectedStock;aiBusy=true;aiError='';render();
 try{const result=await api('/api/ai/summary',{method:'POST',body:{symbol,mode},timeout:125000});if(epoch!==aiEpoch||currentUser?.id!==userId)return;aiSummaries[symbol]=result;}
 catch(error){if(epoch!==aiEpoch)return;aiError=error.message;if(error.status===401)showSignedOut('login');}
 finally{if(epoch===aiEpoch){aiBusy=false;if(currentUser){render();if(page==='insights'&&selectedStock===symbol&&!aiError)$('#related-news .ai-references')?.scrollIntoView({block:'start',behavior:'instant'});}}}
}

function canRedraw(){return !document.activeElement?.closest('form')&&!$('#modal').open;}
function header(title,sub,action=''){return `<div class="page-header"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="heading-actions">${action}</div></div>`;}
const addButton=()=>`<button class="btn primary" data-action="add">${icon('plus')} เลือกบริษัทที่ติดตาม</button>`;
function newsItem(n){return `<article class="news-card">${n.symbol?companyLogo(n.symbol):'<span class="company-logo">US</span>'}<div><div class="news-meta"><span class="ticker-tag">${escapeHtml(n.symbol||'ภาพรวมสหรัฐฯ')}</span><span>${escapeHtml(n.source)}</span>${n.stale?'<span class="sentiment negative">ข้อมูลเก่า · อัปเดตไม่สำเร็จ/ล่าช้า</span>':''}</div><a class="news-title" href="${escapeHtml(n.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(n.title)}</a><div class="news-footer"><span>เผยแพร่ ${escapeHtml(dateLabel(n.publishedAt))}</span><span>${n.sourceType==='finance'?'สื่อการเงิน · ผ่าน Finnhub':n.sourceType==='macro'?'ข่าวเศรษฐกิจ · RSS ทางการ':'ประกาศบริษัท'} · อ่านต้นฉบับ</span>${n.bodySupported?`<button class="text-button" type="button" data-read-article="${escapeHtml(n.id)}">สรุปเนื้อหา</button>`:''}</div></div></article>`;}
function feedStatus(){return `<details class="feed-status"><summary>สถานะแหล่งข่าว ${newsData.sources.filter(s=>s.status==='ok').length}/${newsData.sources.length} เชื่อมต่อสำเร็จ</summary>${newsData.sources.map(s=>`<p><b>${escapeHtml(s.name)}</b> · ${s.status==='ok'?'เชื่อมต่อแล้ว':s.status==='error'?'เชื่อมต่อไม่สำเร็จ':'รอข้อมูล'}${s.enabled?'':' · ปิดในบัญชีนี้'}<br><small>ดึงข้อมูลสำเร็จล่าสุด ${escapeHtml(dateLabel(s.succeededAt))}${s.error?' · '+escapeHtml(s.error):''}</small></p>`).join('')}<p>ตรวจทุก 15 นาทีขณะเซิร์ฟเวอร์ทำงาน เวลาเผยแพร่ข่าวอาจเก่ากว่าเวลาที่ดึงข้อมูล</p></details>`;}
function newsSection(compact=false){const items=newsData.items.filter(n=>newsFilter!=='watchlist'||state.watchlist.includes(n.symbol));return `<section class="card"><div class="section-title"><h2>ข่าวบริษัทและสื่อการเงิน</h2><button class="text-button" data-refresh-news ${newsLoading?'disabled':''}>${newsLoading?'กำลังโหลด…':'รีเฟรช'}</button></div><div class="tabs"><button class="tab ${newsFilter==='all'?'active':''}" data-filter="all">แหล่งข่าวที่เปิดไว้</button><button class="tab ${newsFilter==='watchlist'?'active':''}" data-filter="watchlist">บริษัทที่ฉันเลือก</button></div>${newsError?`<p role="alert" class="form-error">${escapeHtml(newsError)}</p>`:''}${(compact?items.slice(0,5):items).map(newsItem).join('')||`<div class="empty">${newsLoading?'กำลังโหลดข่าว…':'ยังไม่มีข่าวในรายการนี้'}<br><small>ลองรีเฟรช หรือเลือกแหล่งข่าวเพิ่มเติมในหน้าแหล่งข้อมูล</small></div>`}${feedStatus()}<p class="small-note">หัวข้อจาก RSS บริษัท ฟีดเศรษฐกิจที่ตรวจสอบแล้ว และสื่อการเงินผ่าน Finnhub กดสรุปเนื้อหาเพื่ออ่านและสรุปบทความที่รองรับพร้อมลิงก์ต้นฉบับ ข่าวและความเห็นจากสื่อควรตรวจสอบก่อนตัดสินใจ</p></section>`;}
function aiList(title,items){return items?.length?`<div class="ai-detail"><b>${escapeHtml(title)}</b><ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul></div>`:'';}
function aiAnswerCard(item){return `<article class="ai-answer"><div class="ai-answer-meta"><b>คุณถาม: ${escapeHtml(item.question)}</b><time datetime="${escapeHtml(item.answeredAt)}">AI ตอบ ${escapeHtml(dateLabel(item.answeredAt))}</time></div><p>${escapeHtml(item.answer)}</p>${item.sources?.length?`<div class="ai-answer-sources"><b>แหล่งอ้างอิง</b>${item.sources.map(source=>`<a href="${escapeHtml(source.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(source.source)} · ${escapeHtml(source.title)} · ${escapeHtml(dateLabel(source.publishedAt))}</a>`).join('')}</div>`:''}</article>`;}
function aiProviderLabel(provider){return {gemini:'Gemini',groq:'Groq',ollama:'Ollama',headlines:'รวมหัวข้อข่าว'}[provider]||'AI';}
function aiReferences(articles){
 if(!articles?.length)return '';
 return `<details class="ai-sources ai-references" open><summary><span>แหล่งอ้างอิง</span><span class="ai-reference-count">${articles.length} ข่าว</span>${icon('chevron')}</summary><ul class="ai-reference-list">${articles.map(item=>`<li><a href="${escapeHtml(item.url)}" target="_blank" rel="noopener noreferrer"><span class="ai-reference-copy"><span class="ai-reference-publisher">${escapeHtml(item.source)}</span><span class="ai-reference-title">${escapeHtml(item.title)}</span><small>เผยแพร่ ${escapeHtml(dateLabel(item.publishedAt))}${item.stale?' · ข้อมูลเก่า / อัปเดตไม่สำเร็จ':''}</small></span>${icon('external')}</a></li>`).join('')}</ul></details>`;
}
function renderRelatedNews(){
 const result=aiSummaries[selectedStock];
 return `<section class="card related-news-card" id="related-news" aria-labelledby="related-news-title"><div class="section-title"><h2 id="related-news-title">ค้นหาข่าวที่เกี่ยวข้อง</h2><span class="counter">${escapeHtml(selectedStock)}</span></div><p class="small-note">ข่าวของ ${escapeHtml(stock(selectedStock).name)} จากแหล่งข้อมูลที่คุณเปิดไว้</p>${result?`<p class="small-note" role="status">พบ ${result.articles.length} ข่าว · ค้นหาเมื่อ ${escapeHtml(dateLabel(result.createdAt))}</p>${aiReferences(result.articles)}`:''}${aiError?`<p class="form-error" role="alert">${escapeHtml(aiError)}</p><button class="text-button" data-page="sources">จัดการแหล่งข่าว</button>`:''}<button class="btn primary" data-ai-summary="headlines" ${aiBusy||articleBusy||aiQuestionBusy?'disabled':''}>${aiBusy?'กำลังค้นหาข่าว…':'ค้นหาข่าวที่เกี่ยวข้อง'}</button></section>`;
}

function weeklyChart(history){
 const rows=Array.isArray(history)?history.filter(row=>/^\d{4}-\d{2}-\d{2}$/.test(row.date)&&Number.isFinite(row.close)&&row.close>0).slice(-104):[];
 if(rows.length<2)return '';
 const lows=rows.map(row=>row.close),min=Math.min(...lows),max=Math.max(...lows),range=max-min||1;
 const points=rows.map((row,index)=>`${(16+index*608/(rows.length-1)).toFixed(1)},${(150-(row.close-min)*128/range).toFixed(1)}`).join(' ');
 return `<figure class="weekly-chart"><figcaption>ราคาปิดรายสัปดาห์ย้อนหลัง · ปรับ split/ปันผล · USD</figcaption><svg viewBox="0 0 640 172" role="img" aria-label="กราฟราคาปิดรายสัปดาห์จาก ${escapeHtml(rows[0].date)} ถึง ${escapeHtml(rows.at(-1).date)}"><path d="M16 150H624" stroke="#dce5f0" stroke-width="2"/><polyline points="${points}" fill="none" stroke="#587fa9" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="chart-labels"><span>${escapeHtml(rows[0].date)} · ${money(rows[0].close)} USD</span><span>${escapeHtml(rows.at(-1).date)} · ${money(rows.at(-1).close)} USD</span></div></figure>`;
}
function freeForecastCard(){
 const theme=document.documentElement.dataset.theme==='light'?'light':'dark',symbol=selectedStock;
 const technical={interval:forecastInterval,symbol,width:'100%',height:'100%',showIntervalTabs:false,disableInterval:true,displayMode:'single',locale:'th',colorTheme:theme,isTransparent:false,'page-uri':location.origin};
 const chart={symbols:[[stock(symbol).name,symbol+'|1D']],width:'100%',height:'100%',colorTheme:theme,backgroundColor:theme==='light'?'#ffffff':'#211b2c',isTransparent:false,locale:'th',chartOnly:false,showVolume:false,showMA:false,hideDateRanges:true,scalePosition:'right',scaleMode:'Normal',chartType:'area',lineWidth:2,changeMode:'price-and-percent',valuesTracking:'1',dateRanges:['12m|1D'],dateFormat:'MMM dd, yyyy',timeHoursFormat:'24-hours','page-uri':location.origin};
 const url=(widget,settings)=>'https://www.tradingview-widget.com/embed-widget/'+widget+'/?locale=th#'+encodeURIComponent(JSON.stringify(settings));
 return `<section class="card forecast-card" id="forecast-panel" data-mode="widget" aria-labelledby="forecast-title"><div class="section-title"><h2 id="forecast-title">แนวโน้มจากราคาย้อนหลัง · ${escapeHtml(symbol)}</h2><span class="ai-badge">TradingView</span></div><p class="small-note">ข้อมูลจาก TradingView · ราคามีความล่าช้าตามตลาด</p><div class="forecast-widgets"><section><h3>ราคาย้อนหลัง 1 ปี · USD</h3><div class="forecast-history-wrap"><iframe class="forecast-history-widget" loading="lazy" title="กราฟราคาย้อนหลัง 1 ปีของ ${escapeHtml(symbol)}" src="${escapeHtml(url('symbol-overview',chart))}" referrerpolicy="origin" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"></iframe></div></section><section><h3>สรุปสัญญาณทางเทคนิค · ${forecastIntervals[forecastInterval]}</h3><div class="quote-periods forecast-periods" role="group" aria-label="กรอบเวลาสัญญาณทางเทคนิค">${Object.entries(forecastIntervals).map(([key,label])=>`<button type="button" class="btn ${key===forecastInterval?'active':''}" data-forecast-interval="${key}" aria-pressed="${key===forecastInterval}">${label}</button>`).join('')}</div><div class="forecast-technical-wrap"><iframe class="forecast-widget" loading="lazy" title="สัญญาณทางเทคนิค ${forecastIntervals[forecastInterval]}ของ ${escapeHtml(symbol)}" src="${escapeHtml(url('technical-analysis',technical))}" referrerpolicy="origin" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox"></iframe></div></section></div><div class="tradingview-widget-copyright quote-attribution"><a href="https://www.tradingview.com/symbols/${encodeURIComponent(symbol)}/technicals/" target="_blank" rel="noopener noreferrer nofollow">${escapeHtml(stock(symbol).name)} technical analysis by TradingView</a></div><p class="small-note">Sell = แรงขาย · Neutral = กลาง · Buy = แรงซื้อ · สัญญาณอาจเปลี่ยนระหว่างแท่งราคา กราฟแสดงราคา 1 ปี ส่วนปุ่มรายวัน/สัปดาห์/เดือนใช้เลือกกรอบเวลาของตัวชี้วัด</p><p class="risk-inline">สัญญาณจากตัวชี้วัดของ TradingView ไม่ใช่ผลทดสอบย้อนหลังของแอปหรือคำทำนายจาก AI และไม่ใช่คำแนะนำลงทุน</p><div class="forecast-actions"><button class="btn" type="button" data-refresh-forecast>อัปเดตแนวโน้ม</button><a class="text-button" href="https://www.tradingview.com/symbols/${encodeURIComponent(symbol)}/technicals/" target="_blank" rel="noopener noreferrer">เปิดข้อมูลที่ TradingView</a></div></section>`;
}
function forecastCard(){
 const result=forecasts[selectedStock],busy=forecastLoading===selectedStock;
 if(result&&(['no_history','insufficient','stale','error'].includes(result.status)||!result.history?.length))return freeForecastCard();
 let message=busy?'กำลังตรวจข้อมูลราคาย้อนหลัง…':!result?'กำลังเตรียมข้อมูล…':result.status==='no_history'?(result.configured?'ยังไม่มีราคาย้อนหลังที่ใช้ได้':'ยังไม่เชื่อมต่อแหล่งราคาย้อนหลัง'):result.status==='insufficient'?`มีข้อมูล ${result.available} สัปดาห์ ต้องการอย่างน้อย ${result.required} สัปดาห์`:result.status==='stale'?'ราคาย้อนหลังเก่าเกิน 14 วัน จึงงดให้สัญญาณ':result.status==='error'?'ตรวจแนวโน้มไม่สำเร็จ':result.status==='validated'?`สัญญาณทดลองสำหรับสัปดาห์หน้า: ${result.direction==='up'?'ขึ้น':'ลง'}`:result.backtest?.samples<100?'ช่วงทดสอบมีน้อยกว่า 100 สัปดาห์ จึงยังไม่แสดงสัญญาณ':result.backtest?.accuracy<0.6?'ความแม่นยำย้อนหลังต่ำกว่า 60% จึงไม่แสดงสัญญาณ':result.backtest?.accuracy<=result.backtest?.baselineAccuracy?'ผลย้อนหลังไม่ชนะการทายขึ้นเสมอ จึงไม่แสดงสัญญาณ':'ยังไม่แสดงสัญญาณ';
 const test=result?.backtest;
 return `<section class="card forecast-card" id="forecast-panel" data-mode="native"><div class="section-title"><h2>แนวโน้มจากราคาย้อนหลัง · ${escapeHtml(selectedStock)}</h2><span class="ai-badge">${result?.status==='validated'?'ผ่านเกณฑ์ย้อนหลัง':'ทดลอง'}</span></div><p class="forecast-trend">${escapeHtml(message)}</p>${weeklyChart(result?.history)}${test?`<p>แนวโน้มที่เกิดขึ้นแล้วใน 4 สัปดาห์: <b>${result.observedTrend==='up'?'ขึ้น':'ลง'}</b> (ไม่ใช่คำทำนาย)</p><p>มีราคาที่จบสัปดาห์แล้ว ${result.historyWeeks} สัปดาห์ · ทดสอบย้อนหลัง 5 ปี ${test.samples} สัปดาห์ · ถูก ${test.correct} สัปดาห์ (${Math.round(test.accuracy*100)}%) · ทายขึ้นเสมอ ${Math.round(test.baselineAccuracy*100)}%</p><p class="small-note">ราคาปิดปรับ split/ปันผลล่าสุด ${escapeHtml(result.asOf)} · ${money(result.latestClose)} USD · กฎแนวโน้ม 4 สัปดาห์ ทดสอบผลสัปดาห์ถัดไป</p>`:''}${result?.error?`<p class="small-note">${escapeHtml(result.error)}</p>`:''}<p class="risk-inline">ผลทดสอบย้อนหลังไม่รับประกันอนาคต ไม่ใช่คำแนะนำลงทุน และไม่ใช่ผลทำนายจาก AI</p><button class="btn" data-refresh-forecast ${busy?'disabled':''}>${busy?'กำลังโหลด…':'ตรวจแนวโน้ม'}</button></section>`;
}
function renderOverview(){
 const followed=state.watchlist;
 return header('ข่าวที่คุณติดตาม','หัวข้อข่าว แหล่งที่มา และเวลาเผยแพร่',addButton())+`<div class="dashboard-columns"><div class="left-column">${newsSection(true)}</div><aside class="right-column"><section class="card watchlist-summary"><div class="section-title"><h2>รายการติดตาม</h2><span class="counter">${followed.length} บริษัท</span></div>${followed.length?`<ul class="watchlist-rows">${followed.slice(0,6).map(symbol=>`<li>${companyLogo(symbol)}<div><b>${escapeHtml(symbol)}</b><span>${escapeHtml(stock(symbol).name)}</span></div></li>`).join('')}</ul><button class="text-button" data-page="following">จัดการรายการ ${icon('arrow')}</button>`:'<p class="empty">ยังไม่ได้เลือกบริษัท<br>เพิ่มบริษัทเพื่อกรองข่าวที่สนใจ</p><button class="btn" data-action="add">เลือกบริษัท</button>'}<div class="source-summary"><span>${state.sources.filter(s=>s.enabled).length} แหล่งข่าวที่เปิดไว้</span><button class="text-button" data-page="sources">จัดการ</button></div></section><section class="ai-entry"><span data-icon="spark">${icon('spark')}</span><h2>อ่านต่อกับ AI</h2><p>สรุปจากหัวข้อข่าว พร้อมลิงก์ตรวจสอบต้นฉบับ</p><p class="small-note">${aiStatus.available?'พร้อมสรุปเมื่อคุณเลือกบริษัท':'ยังไม่พร้อมสรุปข่าวในขณะนี้'}</p><button class="text-button" data-page="insights">เปิด AI Insights ${icon('arrow')}</button></section></aside></div>`;
}
function renderFollowing(){return header('สิ่งที่ฉันอยากติดตาม','เลือกบริษัทเพื่อกรองข่าว ไม่ต้องกรอกข้อมูลพอร์ต',addButton())+`<section class="card"><div class="section-title"><h2>บริษัทที่เลือก</h2><span class="counter">${state.watchlist.length}</span></div><div class="company-grid">${state.watchlist.map(symbol=>{const s=stock(symbol);return `<article class="card company-card">${companyLogo(symbol)}<h3>${escapeHtml(symbol)}</h3><p>${escapeHtml(s.name)}<br>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><button class="remove" data-unfollow="${escapeHtml(symbol)}">เลิกติดตาม</button></article>`;}).join('')||'<div class="empty">ยังไม่ได้เลือกบริษัท<br>กด “เลือกบริษัทที่ติดตาม” เพื่อบอกสิ่งที่คุณสนใจ</div>'}</div><a class="text-button" href="/api/export" download>ดาวน์โหลดข้อมูลบัญชี JSON</a></section>`;}
function companyCards(){const q=query.trim().toLowerCase(),list=stocks.filter(s=>`${s.symbol} ${s.name} ${s.thai} ${s.sector}`.toLowerCase().includes(q));return list.map(s=>`<article class="card company-card">${companyLogo(s.symbol)}<h3>${escapeHtml(s.symbol)} <span class="unit">US · USD</span></h3><p>${escapeHtml(s.name)}<br>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><button class="btn" data-company="${escapeHtml(s.symbol)}">ดูข้อมูลบริษัท ${icon('arrow')}</button></article>`).join('')||`<div class="empty">ไม่พบในรายชื่อ ${stocks.length} บริษัทที่รองรับ<br>ใช้ปุ่มค้นข่าวบนเว็บด้านบนเพื่อดูข่าวของบริษัทหรือหัวข้ออื่น</div>`;}
function webNewsActions(){const input=query.trim().slice(0,160);if(!input)return '<span class="small-note">พิมพ์ชื่อบริษัทหรือ ticker ด้านบนเพื่อเปิดข่าวจากเว็บค้นหา</span>';const company=stocks.find(stock=>stock.symbol.toLowerCase()===input.toLowerCase());const term=company?`${company.name} ${company.symbol}`:input;return `<a class="btn primary" href="https://news.google.com/search?q=${encodeURIComponent(term)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นใน Google News</a><a class="btn" href="https://www.bing.com/news/search?q=${encodeURIComponent(term)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นใน Bing News</a>`;}
function renderSearch(){return header('ค้นหาบริษัทและข่าวบนเว็บ','พิมพ์ชื่อบริษัท ตัวย่อหุ้น หรือหัวข้อข่าว')+`<label class="large-search">${icon('search')}<input id="company-query" type="search" placeholder="เช่น AVGO, Tesla, หุ้นญี่ปุ่น, AI" value="${escapeHtml(query)}" aria-label="ค้นหาบริษัทหรือข่าวบนเว็บ"></label><section class="card web-news-search"><h2>ค้นข่าวบนเว็บ</h2><p>ค้นได้ทุกคำ รวมบริษัทนอกแค็ตตาล็อก เปิดผลค้นหาจากเว็บไซต์ต้นทางในแท็บใหม่ ไม่ต้องใช้ API key</p><div id="web-news-actions" class="web-news-actions">${webNewsActions()}</div><p class="small-note">ผลขึ้นอยู่กับข่าวที่ผู้ให้บริการค้นหาจัดทำดัชนี ไม่รับประกันว่าครบทุกข่าว และข่าวนอก ${stocks.length} บริษัทจะยังไม่เข้าฟีดหรือ AI ของแอปโดยอัตโนมัติ</p></section><p class="small-note">บริษัทที่ติดตามในแอปได้: ${stocks.length} ตัวที่จดทะเบียนในสหรัฐฯ</p><div class="company-grid" id="company-results">${companyCards()}</div>`;}
function renderAlerts(){const a=state.alerts,items=a.news?newsData.items.filter(n=>a.scope==='all'||state.watchlist.includes(n.symbol)).slice(0,10):[];return header('ข่าวที่ติดตาม & การตั้งค่า','อ่านข่าวที่เกี่ยวข้องในแอป และจัดการบัญชี')+`<section class="card"><h2>ข่าวจากบริษัทที่คุณเลือก</h2>${items.map(newsItem).join('')||'<div class="empty">ยังไม่มีข่าวที่ตรงกับการตั้งค่า</div>'}<p class="small-note">ข่าวแสดงในแอป และส่ง Web Push ได้เมื่อเปิดรับบนอุปกรณ์และเซิร์ฟเวอร์ทำงาน ยังไม่มีอีเมลแจ้งข่าว</p></section><form id="alert-form" class="card settings"><div class="info-box">ตั้งค่าข่าวสำหรับแอปและ Web Push ได้ ส่วนสรุปรายวันและแจ้งแนวโน้มยังไม่เปิดส่งอัตโนมัติ</div>${[['news','แสดงและแจ้ง Push ข่าวบริษัทที่เลือก'],['daily','สรุปรายวัน · ยังไม่เปิดส่ง'],['trend','การเปลี่ยนแนวโน้ม AI · ยังไม่เปิดใช้']].map(([key,label])=>`<label class="setting-row"><span>${label}</span><input class="switch" type="checkbox" name="${key}" ${a[key]?'checked':''}></label>`).join('')}<label class="setting-row">เวลาที่ต้องการรับสรุป (เวลาไทย)<input type="time" name="time" required value="${escapeHtml(a.time)}"></label><label class="setting-row">ขอบเขตข่าว<select name="scope"><option value="watchlist" ${a.scope==='watchlist'?'selected':''}>บริษัทที่ฉันเลือก</option><option value="all" ${a.scope==='all'?'selected':''}>ทุกฟีดที่เปิดไว้</option></select></label><button class="btn primary" type="submit">บันทึกการตั้งค่า</button></form><section class="card settings"><h2>กู้คืนบัญชี</h2><p>เก็บรหัสกู้คืนไว้ในที่ปลอดภัย หากลืมรหัสผ่านใช้รหัสนี้ได้ การสร้างใหม่จะยกเลิกรหัสเดิม</p><button class="btn" data-new-recovery>สร้างรหัสกู้คืนใหม่</button></section>`;}
function render(){if(!currentUser)return;$('.risk-footer').hidden=page!=='insights';const headingFocused=document.activeElement===$('#main h1');if(page==='portfolio')page='following';document.querySelectorAll('.nav,.account-link').forEach(n=>{n.classList.toggle('active',n.dataset.page===page);if(n.dataset.page===page)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});const views={account:renderAccount,welcome:renderWelcome,devices:renderDevices,overview:renderOverview,news:()=>header('ข่าวบริษัทและสื่อการเงิน','หัวข้อข่าวต้นทางพร้อมลิงก์และเวลาเผยแพร่')+newsSection(),following:renderFollowing,search:renderSearch,alerts:renderAlerts,sources:renderSourceManager,insights:()=>header('AI Insights','อ่านสรุปเนื้อหาบทความ ถาม AI และค้นหาข่าวที่เกี่ยวข้อง')+`<div class="wide-ai">${renderArticleCard()}${renderRelatedNews()}${forecastCard()}</div>`};const more=$('[data-mobile-more]');const secondary=['search','alerts','sources','welcome','devices','account'].includes(page);more.classList.toggle('active',secondary);if(secondary)more.setAttribute('aria-current','page');$('#main').innerHTML=views[page]();if(page==='search')$('#main .web-news-search').insertAdjacentHTML('beforebegin',researchPanel());if(['overview','following'].includes(page))$('#main').insertAdjacentHTML('beforeend',quotePanel());updateDock();$('#main h1')?.setAttribute('tabindex','-1');if(headingFocused)$('#main h1')?.focus({preventScroll:true});}
function navigate(next){if(!currentUser)return;if($('#mobile-menu').open)$('#mobile-menu').close();page=next==='portfolio'?'following':next;history.replaceState(null,'','#'+page);render();if(page==='following')loadQuotes();if(page==='insights')loadForecast();$('#main h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();}
function addFollowing(symbol='AAPL'){openModal('เลือกบริษัทที่อยากให้ติดตาม',`<form id="following-form"><label class="field">บริษัท<select name="symbol">${stocks.filter(s=>!state.watchlist.includes(s.symbol)||s.symbol===symbol).map(s=>`<option value="${s.symbol}" ${s.symbol===symbol?'selected':''}>${s.symbol} — ${s.name}</option>`).join('')}</select></label><p class="form-help">เราเก็บเฉพาะชื่อบริษัทที่เลือก ไม่ขอจำนวนหุ้นหรือต้นทุน</p><p class="form-error" role="alert"></p><button class="btn primary" type="submit">ติดตามข่าวบริษัทนี้</button></form>`);}
document.addEventListener('click',async e=>{
 if(!currentUser)return;const el=e.target.closest('button,a');if(!el)return;if(isSaving){toast('กำลังบันทึก กรุณารอสักครู่');return;}
 if(el.hasAttribute('data-mobile-more')){$('#mobile-menu').showModal();el.setAttribute('aria-expanded','true');}if(el.hasAttribute('data-close-mobile'))$('#mobile-menu').close();if(el.dataset.page)navigate(el.dataset.page);if(el.id==='quick-search'){navigate('search');$('#company-query').focus();}if(el.id==='close-modal')$('#modal').close();
 if(el.hasAttribute('data-ai-summary'))runAISummary(el.dataset.aiSummary||'ai');
 if(el.hasAttribute('data-recheck-ai')){if(aiBusy||aiQuestionBusy)return;el.disabled=true;await loadAIStatus();render();}
 if(el.dataset.forecastInterval&&Object.hasOwn(forecastIntervals,el.dataset.forecastInterval)){forecastInterval=el.dataset.forecastInterval;render();$(`[data-forecast-interval="${forecastInterval}"]`)?.focus({preventScroll:true});}
 if(el.hasAttribute('data-refresh-forecast')){delete forecasts[selectedStock];loadForecast();}
 if(el.dataset.filter){newsFilter=el.dataset.filter;render();}if(el.hasAttribute('data-refresh-news')){loadNews();render();}if(el.dataset.action==='add')addFollowing();
 if(el.dataset.unfollow)openModal('เลิกติดตามบริษัท',`<p>เลิกติดตามข่าว ${escapeHtml(el.dataset.unfollow)}?</p><button class="btn primary" data-confirm-unfollow="${escapeHtml(el.dataset.unfollow)}">ยืนยันเลิกติดตาม</button>`);
 if(el.dataset.confirmUnfollow){state.watchlist=state.watchlist.filter(symbol=>symbol!==el.dataset.confirmUnfollow);const ok=await save();if(ok){$('#modal').close();render();toast('อัปเดตรายการที่ติดตามแล้ว');}}
 if(el.dataset.company){const s=stock(el.dataset.company),followed=state.watchlist.includes(s.symbol);openModal(s.symbol+' · '+s.name,`<p>${escapeHtml(s.thai)} · ${escapeHtml(s.sector)}</p><p><a class="text-button" href="${escapeHtml(s.url)}" target="_blank" rel="noopener noreferrer">เว็บไซต์นักลงทุนสัมพันธ์</a></p><p><a class="text-button" href="https://news.google.com/search?q=${encodeURIComponent(`${s.name} ${s.symbol}`)}" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">ค้นข่าวบริษัทบนเว็บ</a></p><p><a class="text-button" href="https://www.sec.gov/edgar/search/#/q=${encodeURIComponent(s.symbol)}" target="_blank" rel="noopener noreferrer">ค้นเอกสารกับ SEC EDGAR</a></p>${followed?'<div class="info-box">ติดตามข่าวบริษัทนี้แล้ว</div>':`<button class="btn primary" data-follow-symbol="${s.symbol}">ติดตามข่าวบริษัทนี้</button>`}`);}
 if(el.dataset.followSymbol){state.watchlist.push(el.dataset.followSymbol);if(await save()){selectedStock=el.dataset.followSymbol;$('#modal').close();render();toast('เพิ่มบริษัทที่ติดตามแล้ว');}}
 if(el.hasAttribute('data-new-recovery'))openModal('สร้างรหัสกู้คืนใหม่','<form id="new-recovery-form"><label class="field">ยืนยันรหัสผ่านปัจจุบัน<input type="password" name="password" autocomplete="current-password" maxlength="128" required></label><p class="form-error" role="alert"></p><button class="btn primary" type="submit">สร้างรหัสใหม่</button></form>');
});
document.addEventListener('input',e=>{if(e.target.id==='company-query'){query=e.target.value;$('#company-results').innerHTML=companyCards();$('#web-news-actions').innerHTML=webNewsActions();}});
document.addEventListener('change',e=>{if(e.target.id==='ai-symbol'){selectedStock=e.target.value;render();if(page==='insights')loadForecast();}});
document.addEventListener('submit',async e=>{
 if(!currentUser)return;const f=e.target;if(isSaving){e.preventDefault();return;}
 if(f.id==='following-form'){e.preventDefault();const symbol=f.elements.symbol.value;if(!state.watchlist.includes(symbol))state.watchlist.push(symbol);const button=f.querySelector('[type=submit]');button.disabled=true;const ok=await save();if(ok){selectedStock=symbol;$('#modal').close();render();toast(`ติดตามข่าว ${symbol} แล้ว`);}else if(f.isConnected){f.querySelector('.form-error').textContent=lastSaveError;button.disabled=false;}}
 if(f.id==='alert-form'){e.preventDefault();state.alerts={daily:f.elements.daily.checked,news:f.elements.news.checked,trend:f.elements.trend.checked,time:f.elements.time.value,scope:f.elements.scope.value};if(await save()){render();toast('บันทึกการตั้งค่าแล้ว');}}
 if(f.id==='new-recovery-form'){e.preventDefault();const epoch=authEpoch,userId=currentUser.id;const button=f.querySelector('button');if(button.disabled)return;button.disabled=true;try{const result=await api('/api/recovery-code',{method:'POST',body:{password:f.elements.password.value}});if(sameSession(epoch,userId)&&f.isConnected&&$('#modal').open)openModal('เก็บรหัสกู้คืนใหม่',recoveryNotice(result.recoveryCode));}catch(error){if(sameSession(epoch,userId)&&f.isConnected){if(error.status===401)showSignedOut('login');else f.querySelector('.form-error').textContent=error.message;}}finally{if(f.isConnected)button.disabled=false;}}
});
document.addEventListener('keydown',e=>{if(currentUser&&e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#modal').open){e.preventDefault();navigate('search');$('#company-query').focus();}});
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
setInterval(()=>{if(currentUser&&!isSaving&&document.visibilityState==='visible')loadNews({redraw:!$('#modal').open});},5*60*1000);

$('#mobile-menu').addEventListener('close',()=>{$('[data-mobile-more]').setAttribute('aria-expanded','false');});

// The tray is UI geometry; all destination glyphs remain canonical Lucide assets.
function updateDock(){
 const dock=$('.app-dock');if(!dock||!currentUser||!dock.clientWidth)return;
 const active=dock.querySelector('[aria-current="page"]')||dock.querySelector('[data-mobile-more]');
 const x=active.offsetLeft+active.offsetWidth/2,w=dock.clientWidth,h=86,r=16,shoulder=Math.min(36,x-17,w-x-17);
 dock.style.setProperty('--dock-x',`${x}px`);
 dock.querySelector('.dock-bead').innerHTML=icon(active.dataset.dockIcon);
 const surface=dock.querySelector('.dock-surface');surface.setAttribute('viewBox',`0 0 ${w} ${h}`);
 surface.querySelector('path').setAttribute('d',`M${r} 20 H${x-shoulder} C${x-24} 20 ${x-26} 47 ${x} 47 C${x+26} 47 ${x+24} 20 ${x+shoulder} 20 H${w-r} Q${w} 20 ${w} ${20+r} V${h-r} Q${w} ${h} ${w-r} ${h} H${r} Q0 ${h} 0 ${h-r} V${20+r} Q0 20 ${r} 20 Z`);
}
new ResizeObserver(updateDock).observe($('.app-dock'));
$('.app-dock').addEventListener('keydown',event=>{
 if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
 const buttons=[...$('.app-dock').querySelectorAll('button')],index=buttons.indexOf(document.activeElement);if(index<0)return;
 event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?buttons.length-1:(index+(event.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();
});

new MutationObserver(()=>{const panel=$('#forecast-panel');if(currentUser&&panel?.dataset.mode==='widget')panel.outerHTML=forecastCard();}).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
